1	/**
2	 * @module useProductSalesData
3	 *
4	 * Hook memoizado que processa histórico de vendas a partir de JSON
5	 * estático, calculando estatísticas por dia da semana, tendência
6	 * e sugestão de quantidade para cada produto.
7	 */
8	
9	import { useMemo } from 'react';
10	import { wideDebug } from '@/shared/lib/telemetry/wide-events';
11	import salesDataRaw from '@/shared/data/sales_history.json';
12	import {
13	  startOfDay,
14	  parseISO,
15	  differenceInDays,
16	  endOfDay,
17	  subDays,
18	} from 'date-fns';
19	
20	/** Registro de venda diária com quantidade, dia da semana e preço médio. */
21	export interface DailySale {
22	  date: string;
23	  quantity: number;
24	  weekday: string;
25	  avgPrice?: number;
26	  total?: number;
27	}
28	
29	/** Estatísticas de venda para um dia da semana: média, min, max e desvio padrão. */
30	export interface WeekdayStats {
31	  avg: number;
32	  min: number;
33	  max: number;
34	  stdDev: number;
35	  count: number;
36	}
37	
38	/** Análise completa de um produto: stats por dia, tendência e sugestão de pedido. */
39	export interface ProductAnalysis {
40	  id: string;
41	  name: string;
42	  code: string;
43	  category: string;
44	  stats: Record<string, WeekdayStats>;
45	  overallAvg: number;
46	  periodAvg: number;
47	  suggestion: number;
48	  trending: 'up' | 'down' | 'stable';
49	  salesHistory: DailySale[];
50	}
51	
52	interface ProductHistory {
53	  productName: string;
54	  productCode: string;
55	  category: string;
56	  categoryType?: string;
57	  storeName: string;
58	  salesHistory: DailySale[];
59	}
60	
61	const WEEKDAYS = [
62	  'segunda-feira',
63	  'terça-feira',
64	  'quarta-feira',
65	  'quinta-feira',
66	  'sexta-feira',
67	  'sábado',
68	  'domingo',
69	];
70	
71	interface UseProductSalesDataProps {
72	  selectedStore?: string | null;
73	  targetWeekday?: string;
74	  daysToAnalyze?: number;
75	}
76	
77	/**
78	 * Processa histórico de vendas JSON e calcula estatísticas por produto.
79	 *
80	 * Filtra por loja, agrupa vendas por dia da semana dentro do período
81	 * de análise e calcula média, desvio padrão, tendência e sugestão
82	 * de quantidade (média + 0.5 * desvio) para o dia alvo.
83	 *
84	 * @param selectedStore  - Nome da loja para filtro (opcional).
85	 * @param targetWeekday  - Dia da semana alvo (padrão: hoje).
86	 * @param daysToAnalyze  - Janela de dias para análise (padrão: 30).
87	 * @returns Lista de produtos analisados e dia da semana efetivo.
88	 */
89	export function useProductSalesData({
90	  selectedStore,
91	  targetWeekday,
92	  daysToAnalyze = 30,
93	}: UseProductSalesDataProps = {}) {
94	  // Default to today's weekday if not provided
95	  const effectiveWeekday =
96	    targetWeekday ||
97	    new Date().toLocaleDateString('pt-BR', { weekday: 'long' });
98	
99	  const processedData = useMemo(() => {
100	    let rawData = salesDataRaw as ProductHistory[];
101	
102	    // Filter by store if selected
103	    if (selectedStore) {
104	      wideDebug('produtos.sales_data_filter', `Filtrando por loja: "${selectedStore}"`, { domain: 'produtos', attributes: { store: selectedStore } });
105	
106	      // Flexible matching for store name (bidirectional check)
107	      rawData = rawData.filter((p) => {
108	        const jsonStore = p.storeName.toLowerCase();
109	        const selected = selectedStore.toLowerCase();
110	        const match =
111	          jsonStore.includes(selected) || selected.includes(jsonStore);
112	        if (!match && Math.random() < 0.001) {
113	          wideDebug('produtos.sales_data_mismatch', `Mismatch: JSON "${p.storeName}" vs Selected "${selectedStore}"`, { domain: 'produtos', attributes: { jsonStore: p.storeName, selectedStore } });
114	        }
115	        return match;
116	      });
117	      wideDebug('produtos.sales_data_filtered', `Encontrados ${rawData.length} produtos após filtro`, { domain: 'produtos', attributes: { count: rawData.length, store: selectedStore } });
118	    }
119	
120	    // Determine date range based on latest available data
121	    const allDates: string[] = [];
122	    rawData.forEach((product) => {
123	      product.salesHistory.forEach((sale) => {
124	        allDates.push(sale.date);
125	      });
126	    });
127	
128	    const lastDataDate =
129	      allDates.length > 0
130	        ? startOfDay(parseISO(allDates.sort((a, b) => b.localeCompare(a))[0]))
131	        : startOfDay(new Date());
132	
133	    const startDate = subDays(lastDataDate, daysToAnalyze);
134	
135	    return rawData.map((product) => {
136	      const byWeekday: Record<string, number[]> = {};
137	      WEEKDAYS.forEach((d) => (byWeekday[d] = []));
138	
139	      const sortedHistory = [...product.salesHistory].sort((a, b) =>
140	        b.date.localeCompare(a.date),
141	      );
142	
143	      // Filter history by date range
144	      const historyInPeriod = sortedHistory.filter((sale) => {
145	        const saleDate = parseISO(sale.date);
146	        return saleDate >= startDate && saleDate <= endOfDay(lastDataDate);
147	      });
148	
149	      const sumPeriod = historyInPeriod.reduce(
150	        (acc, curr) => acc + curr.quantity,
151	        0,
152	      );
153	      const daysInPeriod = Math.max(
154	        differenceInDays(lastDataDate, startDate) + 1,
155	        1,
156	      );
157	      const periodAvg = sumPeriod / daysInPeriod;
158	
159	      // Populate weekday stats
160	      historyInPeriod.forEach((sale) => {
161	        if (byWeekday[sale.weekday])
162	          byWeekday[sale.weekday].push(sale.quantity);
163	      });
164	
165	      const stats: Record<string, WeekdayStats> = {};
166	      let totalQty = 0,
167	        totalDays = 0;
168	
169	      WEEKDAYS.forEach((day) => {
170	        const quantities = byWeekday[day];
171	        const count = quantities.length;
172	        if (count === 0) {
173	          stats[day] = { avg: 0, min: 0, max: 0, stdDev: 0, count: 0 };
174	          return;
175	        }
176	        const sum = quantities.reduce((a, b) => a + b, 0);
177	        const avg = sum / count;
178	        const variance =
179	          quantities.reduce((acc, val) => acc + Math.pow(val - avg, 2), 0) /
180	          count;
181	        stats[day] = {
182	          avg,
183	          min: Math.min(...quantities),
184	          max: Math.max(...quantities),
185	          stdDev: Math.sqrt(variance),
186	          count,
187	        };
188	        totalQty += sum;
189	        totalDays += count;
190	      });
191	
192	      const overallAvg = totalDays > 0 ? totalQty / totalDays : 0;
193	      let trending: 'up' | 'down' | 'stable' = 'stable';
194	      if (periodAvg > overallAvg * 1.1) trending = 'up';
195	      else if (periodAvg < overallAvg * 0.9) trending = 'down';
196	
197	      const targetStats = stats[effectiveWeekday];
198	      // Suggestion logic: Avg + 0.5 * StdDev to cover volatility
199	      const suggestion = targetStats
200	        ? Math.ceil(targetStats.avg + targetStats.stdDev * 0.5)
201	        : 0;
202	
203	      return {
204	        id: product.productCode,
205	        name: product.productName,
206	        code: product.productCode,
207	        category: product.category,
208	        stats,
209	        overallAvg,
210	        periodAvg,
211	        suggestion,
212	        trending,
213	        salesHistory: sortedHistory,
214	      } as ProductAnalysis;
215	    });
216	  }, [selectedStore, daysToAnalyze, effectiveWeekday]);
217	
218	  return {
219	    products: processedData,
220	    targetWeekday: effectiveWeekday,
221	  };
222	}
223

1	/**
2	 * @module useProductAliases
3	 *
4	 * Hook para gestão de apelidos (aliases) de produtos. Permite
5	 * aprender novas variações de nome e buscar produtos por alias
6	 * normalizado, removendo acentos, plurais e caracteres especiais.
7	 */
8	
9	import { useState, useCallback, useEffect } from 'react';
10	import { supabase } from '@/integrations/supabase/client';
11	import { toast } from 'sonner';
12	import { handleError } from '@/shared/lib/error-handler';
13	import { wideDebug } from '@/shared/lib/telemetry/wide-events';
14	
15	/** Apelido (variação de nome) vinculado a um produto. */
16	export interface ProductAlias {
17	  id: number;
18	  produto_id: number;
19	  alias: string;
20	  used_count: number;
21	}
22	
23	/**
24	 * Normaliza texto para comparação de aliases: remove acentos,
25	 * caracteres especiais, plural simples e converte para minúsculas.
26	 *
27	 * @param text - Texto a ser normalizado.
28	 * @returns String normalizada para comparação.
29	 */
30	export function normalizeAlias(text: string): string {
31	  if (!text) return '';
32	
33	  return (
34	    text
35	      // Remove acentos e diacríticos
36	      .normalize('NFD')
37	      .replace(/[\u0300-\u036f]/g, '')
38	      // Remove caracteres especiais (mantém letras, números e espaços)
39	      .replace(/[^a-zA-Z0-9\s]/g, '')
40	      // Converte para minúsculas
41	      .toLowerCase()
42	      // Remove 's' final de palavras (plural simples) - CUIDADO: pode afetar palavras terminadas em s como "oásis"
43	      // Mas para fins de alias, "copo" e "copos" devem ser o mesmo.
44	      .replace(/s\b/g, '')
45	      // Remove espaços extras
46	      .replace(/\s+/g, ' ')
47	      .trim()
48	  );
49	}
50	
51	/**
52	 * Gerencia apelidos de produtos com aprendizado automático.
53	 *
54	 * Carrega aliases da tabela `produto_aliases`, permite adicionar
55	 * novos aliases normalizados e buscar produto por texto via
56	 * `findProductByAlias`.
57	 *
58	 * @returns Aliases, estado de loading e funções de CRUD/busca.
59	 */
60	export function useProductAliases() {
61	  const [aliases, setAliases] = useState<ProductAlias[]>([]);
62	  const [loading, setLoading] = useState(false);
63	
64	  // Carregar todos os aliases ao iniciar (pode ser otimizado depois se crescer muito)
65	  const fetchAliases = useCallback(async () => {
66	    setLoading(true);
67	    try {
68	      const { data, error } = await (supabase as any)
69	        .from('produto_aliases')
70	        .select('*, produtos_master!inner(ativo)')
71	        .eq('produtos_master.ativo', true);
72	
73	      if (error) {
74	        handleError(error, { domain: 'produtos', operation: 'fetchAliases', showToast: false });
75	        return;
76	      }
77	
78	      setAliases(data || []);
79	    } catch (error) {
80	      handleError(error, { domain: 'produtos', operation: 'fetchAliases', showToast: false });
81	    } finally {
82	      setLoading(false);
83	    }
84	  }, []);
85	
86	  // Adicionar novo alias
87	  const addAlias = useCallback(
88	    async (produtoId: number, aliasText: string, silent = false) => {
89	      if (!aliasText || !produtoId) return null;
90	
91	      // Normalização agressiva antes de salvar
92	      const normalizedAlias = normalizeAlias(aliasText);
93	
94	      // Se após normalização ficar vazio (ex: só tinha caracteres especiais), aborta
95	      if (!normalizedAlias || normalizedAlias.length < 2) return null;
96	
97	      // Verificar se já existe localmente para evitar chamada desnecessária
98	      const exists = aliases.some(
99	        (a) => normalizeAlias(a.alias) === normalizedAlias,
100	      );
101	      if (exists) {
102	        wideDebug('produtos.alias_already_known', 'Alias já conhecido (match normalizado)', { domain: 'produtos', attributes: { alias: normalizedAlias } });
103	        return null;
104	      }
105	
106	      try {
107	        const { data, error } = await (supabase as any)
108	          .from('produto_aliases')
109	          .insert({
110	            produto_id: produtoId,
111	            alias: normalizedAlias,
112	          })
113	          .select()
114	          .single();
115	
116	        if (error) {
117	          // Se for erro de duplicidade (código 23505), apenas ignoramos
118	          if (error.code === '23505') {
119	            wideDebug('produtos.alias_duplicate', 'Alias já existe no banco', { domain: 'produtos', attributes: { alias: normalizedAlias } });
120	            return null;
121	          }
122	          handleError(error, { domain: 'produtos', operation: 'addAlias', showToast: false });
123	          toast.error('Erro ao salvar variação do produto');
124	          return null;
125	        }
126	
127	        // Atualizar estado local
128	        setAliases((prev) => [...prev, data]);
129	        if (!silent) toast.success('Nova variação aprendida pelo sistema!');
130	        return data;
131	      } catch (error) {
132	        handleError(error, { domain: 'produtos', operation: 'addAlias', showToast: false });
133	        return null;
134	      }
135	    },
136	    [aliases],
137	  );
138	
139	  // Buscar produto por alias (retorna ID do produto ou null)
140	  const findProductByAlias = useCallback(
141	    (text: string): number | null => {
142	      if (!text) return null;
143	
144	      const normalizedInput = normalizeAlias(text);
145	      if (!normalizedInput) return null;
146	
147	      // Busca com normalização em ambos os lados
148	      const found = aliases.find(
149	        (a) => normalizeAlias(a.alias) === normalizedInput,
150	      );
151	
152	      if (found) {
153	        wideDebug('produtos.alias_match', `Alias encontrado: "${text}" -> "${normalizedInput}"`, { domain: 'produtos', attributes: { text, normalizedInput, produtoId: found.produto_id } });
154	      }
155	
156	      return found ? found.produto_id : null;
157	    },
158	    [aliases],
159	  );
160	
161	  // Carregar aliases na montagem
162	  useEffect(() => {
163	    fetchAliases();
164	  }, [fetchAliases]);
165	
166	  return {
167	    aliases,
168	    loading,
169	    fetchAliases,
170	    addAlias,
171	    findProductByAlias,
172	  };
173	}
