2	 * Hook de cargos — leitura, criação, edição, inativação.
3	 */
4	
5	import { useState, useEffect, useCallback } from 'react';
6	import { supabase } from '@/integrations/supabase/client';
7	import { toast } from '@/shared/hooks/use-toast';
8	import type { Cargo, CargoInput } from '../types';
9	
10	export function useCargos() {
11	  const [cargos, setCargos] = useState<Cargo[]>([]);
12	  const [loading, setLoading] = useState(true);
13	
14	  const fetchCargos = useCallback(async () => {
15	    setLoading(true);
16	    try {
17	      const { data, error } = await supabase
18	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
19	        .from('cargos' as any)
20	        .select('*')
21	        .order('area', { ascending: true })
22	        .order('nome', { ascending: true });
23	      if (error) throw error;
24	      setCargos((data as unknown as Cargo[]) ?? []);
25	    } catch (err) {
26	      // eslint-disable-next-line no-console
27	      console.error('[useCargos] fetch error', err);
28	      toast({
29	        title: 'Erro',
30	        description: 'Não foi possível carregar a lista de cargos.',
31	        variant: 'destructive',
32	      });
33	    } finally {
34	      setLoading(false);
35	    }
36	  }, []);
37	
38	  useEffect(() => {
39	    fetchCargos();
40	  }, [fetchCargos]);
41	
42	  const createCargo = useCallback(
43	    async (input: CargoInput): Promise<Cargo | null> => {
44	      try {
45	        const { data, error } = await supabase
46	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
47	          .from('cargos' as any)
48	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
49	          .insert(input as any)
50	          .select()
51	          .single();
52	        if (error) throw error;
53	        toast({ title: 'Cargo criado', description: input.nome });
54	        await fetchCargos();
55	        return data as unknown as Cargo;
56	      } catch (err) {
57	        // eslint-disable-next-line no-console
58	        console.error('[useCargos] create error', err);
59	        toast({
60	          title: 'Erro ao criar cargo',
61	          description: err instanceof Error ? err.message : 'Erro desconhecido',
62	          variant: 'destructive',
63	        });
64	        return null;
65	      }
66	    },
67	    [fetchCargos],
68	  );
69	
70	  const updateCargo = useCallback(
71	    async (id: string, patch: Partial<CargoInput>): Promise<boolean> => {
72	      try {
73	        const { error } = await supabase
74	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
75	          .from('cargos' as any)
76	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
77	          .update(patch as any)
78	          .eq('id', id);
79	        if (error) throw error;
80	        toast({ title: 'Cargo atualizado' });
81	        await fetchCargos();
82	        return true;
83	      } catch (err) {
84	        // eslint-disable-next-line no-console
85	        console.error('[useCargos] update error', err);
86	        toast({
87	          title: 'Erro ao atualizar cargo',
88	          description: err instanceof Error ? err.message : 'Erro desconhecido',
89	          variant: 'destructive',
90	        });
91	        return false;
92	      }
93	    },
94	    [fetchCargos],
95	  );
96	
97	  const toggleAtivo = useCallback(
98	    async (id: string, ativo: boolean) => {
99	      return updateCargo(id, { ativo });
100	    },
101	    [updateCargo],
102	  );
103	
104	  return { cargos, loading, fetchCargos, createCargo, updateCargo, toggleAtivo };
105	}
