48	/**
49	 * Busca registros financeiros do Supabase para o período e unidade
50	 * informados, agrega por categorias e monta a DRE completa.
51	 *
52	 * @param period     - Período no formato `MM/YYYY`.
53	 * @param unitFilter - Slug da unidade (`asa_sul`, `lago_sul`, etc.) ou `all`.
54	 * @returns Query do react-query com `dre`, `metrics` e `efficiency`.
55	 */
56	export const useFinancialData = (period: string, unitFilter: string) => {
57	  return useQuery({
58	    queryKey: ['financial-data-v3', period, unitFilter],
59	    queryFn: () => withTrace('financeiro.dre_pnl.carregar', async () => {
60	      const start = performance.now();
61	      wideDebug('financeiro.financial_data.fetch', 'Buscando dados financeiros', {
62	        domain: 'financeiro',
63	        attributes: { unitFilter, period },
64	      });
65	
66	      // 1. Parse Date Range (MM/YYYY)
67	      // Example '01/2025' -> Start: 2025-01-01, End: 2025-01-31
68	      const [monthStr, yearStr] = period.split('/');
69	      const month = parseInt(monthStr, 10);
70	      const year = parseInt(yearStr, 10);
71	
72	      const startDate = new Date(year, month - 1, 1)
73	        .toISOString()
74	        .split('T')[0];
75	      const endDate = new Date(year, month, 0).toISOString().split('T')[0]; // Last day of month
76	
