/**
 * @module useSetores
 *
 * Hook de gestão de setores de produtos. Busca setores ativos,
 * agrega contagem de produtos ativos por setor e expõe operações
 * de criar, mover itens, excluir setor e atualizar produto.
 *
 * REGRA INVIOLÁVEL: nunca altera produtos com ativo=false em produtos_master.
 */

import { useQuery, useQueryClient } from '@tanstack/react-query';
import { supabase } from '@/integrations/supabase/client';

/** Setor com contagem de produtos ativos vinculados. */
export interface SetorComContagem {
  nome: string;
  itensAtivos: number;
}

/** Resultado estruturado de operações de mutação. */
export interface SetorResult {
  ok: boolean;
  error?: string;
  movidos?: number;
}

/**
 * Busca setores ativos e agrega contagem de produtos ativos por setor.
 *
 * Usa uma única query de produtos_master (todos com ativo=true) e
 * conta client-side, evitando N+1 queries ao banco.
 */
async function fetchSetoresComContagem(): Promise<SetorComContagem[]> {
  const [setoresRes, produtosRes] = await Promise.all([
    // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
    supabase.from('setores').select('nome').eq('ativo', true).order('nome'),
    supabase
      .from('produtos_master')
      .select('setor')
      .eq('ativo', true),
  ]);

  if (setoresRes.error) throw setoresRes.error;
  if (produtosRes.error) throw produtosRes.error;

  const setoresData = (setoresRes.data ?? []) as { nome: string }[];
  const produtosData = (produtosRes.data ?? []) as { setor: string | null }[];

  // Agregar contagem de produtos por nome de setor (client-side)
  const contagemPorSetor = new Map<string, number>();
  for (const produto of produtosData) {
    if (produto.setor) {
      contagemPorSetor.set(
        produto.setor,
        (contagemPorSetor.get(produto.setor) ?? 0) + 1,
      );
    }
  }

  return setoresData.map((s) => ({
    nome: s.nome,
    itensAtivos: contagemPorSetor.get(s.nome) ?? 0,
  }));
}

/**
 * Hook de gestão de setores de produtos.
 *
 * Fornece lista de setores ativos com contagem de itens e funções
 * para criar, mover itens entre setores, excluir e atualizar produto.
 */
export function useSetores() {
  const queryClient = useQueryClient();

  const { data, isLoading, refetch } = useQuery<SetorComContagem[]>({
    queryKey: ['setores-gestao'],
    queryFn: fetchSetoresComContagem,
  });

  const setores: SetorComContagem[] = data ?? [];

  /**
   * Cria um novo setor (normalizado para UPPERCASE).
   * Se existir inativo, reativa. Se existir ativo, retorna erro de duplicata.
   */
  async function criarSetor(nome: string): Promise<SetorResult> {
    const norm = nome.trim().toUpperCase();
    if (!norm) return { ok: false, error: 'Informe um nome.' };

    // Buscar setor existente (ativo ou inativo)
    const { data: existente, error: buscaError } = await (
      // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
      supabase.from('setores').select('nome, ativo').eq('nome', norm).maybeSingle()
    );

    if (buscaError) return { ok: false, error: buscaError.message };

    if (existente) {
      if ((existente as { nome: string; ativo: boolean }).ativo) {
        return { ok: false, error: 'Esse setor já existe.' };
      }
      // Reativar setor inativo
      const { error: reativarError } = await (
        // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
        supabase.from('setores').update({ ativo: true }).eq('nome', norm)
      );
      if (reativarError) return { ok: false, error: reativarError.message };
      await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
      return { ok: true };
    }

    // Inserir novo setor
    const { error: insertError } = await (
      // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
      supabase.from('setores').insert({ nome: norm, ativo: true })
    );
    if (insertError) return { ok: false, error: insertError.message };

    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
    return { ok: true };
  }

  /**
   * Move todos os produtos ativos do setor 'de' para o setor 'para'.
   * Nunca toca em produtos com ativo=false.
   */
  async function moverItens(de: string, para: string): Promise<SetorResult> {
    if (!de || !para) return { ok: false, error: 'Informe os dois setores.' };
    if (de === para) return { ok: false, error: 'Setores de origem e destino são iguais.' };

    // Contar quantos serão movidos antes do update
    const { count, error: countError } = await supabase
      .from('produtos_master')
      .select('id', { count: 'exact', head: true })
      .eq('setor', de)
      .eq('ativo', true);

    if (countError) return { ok: false, error: countError.message };

    const movidos = count ?? 0;

    if (movidos === 0) {
      await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
      return { ok: true, movidos: 0 };
    }

    const { error: updateError } = await supabase
      .from('produtos_master')
      .update({ setor: para })
      .eq('setor', de)
      .eq('ativo', true);

    if (updateError) return { ok: false, error: updateError.message };

    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
    return { ok: true, movidos };
  }

  /**
   * Exclui um setor. Bloqueia se houver produtos ativos apontando para ele.
   * Produtos inativos que ainda referenciam o nome são deixados intocados.
   */
  async function excluirSetor(nome: string): Promise<SetorResult> {
    // Contar produtos ativos com esse setor
    const { count, error: countError } = await supabase
      .from('produtos_master')
      .select('id', { count: 'exact', head: true })
      .eq('setor', nome)
      .eq('ativo', true);

    if (countError) return { ok: false, error: countError.message };

    const total = count ?? 0;
    if (total > 0) {
      return {
        ok: false,
        error: `Mova os ${total} itens ativos antes de excluir.`,
      };
    }

    const { error: deleteError } = await (
      // @ts-expect-error tabela 'setores' não está nos tipos gerados ainda
      supabase.from('setores').delete().eq('nome', nome)
    );
    if (deleteError) return { ok: false, error: deleteError.message };

    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
    return { ok: true };
  }

  /**
   * Atualiza setor e unidade_medida de um produto ativo pelo id.
   * Nunca toca em outros campos nem em produtos inativos.
   */
  async function atualizarProdutoSetorUnidade(
    produtoId: number,
    setor: string,
    unidade: string,
  ): Promise<SetorResult> {
    const { error } = await supabase
      .from('produtos_master')
      .update({ setor, unidade_medida: unidade })
      .eq('id', produtoId);

    if (error) return { ok: false, error: error.message };

    await queryClient.invalidateQueries({ queryKey: ['setores-gestao'] });
    return { ok: true };
  }

  return {
    setores,
    isLoading,
    refetch,
    criarSetor,
    moverItens,
    excluirSetor,
    atualizarProdutoSetorUnidade,
  };
}

/**
 * @module useSetores.test
 *
 * Testes unitários do hook useSetores.
 * Cobrem: excluirSetor (bloqueio e deleção), criarSetor (normalização +
 * deduplicação) e atualizarProdutoSetorUnidade (campos corretos).
 */

import { createElement, type ReactNode } from 'react';
import { renderHook, act, waitFor } from '@testing-library/react';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { supabase } from '@/integrations/supabase/client';
import { useSetores } from './useSetores';

// ─── helpers ────────────────────────────────────────────────────────────────

function createWrapper() {
  const client = new QueryClient({
    defaultOptions: {
      queries: { retry: false, gcTime: 0 },
      mutations: { retry: false },
    },
  });
  return ({ children }: { children: ReactNode }) =>
    createElement(QueryClientProvider, { client }, children);
}

/**
 * Configura o mock de supabase.from() para uma sequência de chamadas.
 * Cada entrada em `tableHandlers` é um mapa de nome-de-tabela para a
 * chain encadeável que esse .from() deve retornar.
 *
 * Usa mockImplementation para retornar builders diferentes conforme
 * a tabela solicitada.
 */
function setupFromMock(
  tableHandlers: Record<string, Record<string, unknown>>,
) {
  (supabase.from as ReturnType<typeof vi.fn>).mockImplementation(
    (table: string) => {
      return tableHandlers[table] ?? makeChain({});
    },
  );
}

/** Constrói uma chain encadeável genérica que resolve para `result`. */
function makeChain(
  result: unknown,
  overrides: Record<string, unknown> = {},
): Record<string, unknown> {
  const chain: Record<string, unknown> = {
    select: vi.fn().mockReturnThis(),
    insert: vi.fn().mockReturnThis(),
    update: vi.fn().mockReturnThis(),
    delete: vi.fn().mockReturnThis(),
    upsert: vi.fn().mockReturnThis(),
    eq: vi.fn().mockReturnThis(),
    neq: vi.fn().mockReturnThis(),
    order: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    head: vi.fn().mockReturnThis(),
    maybeSingle: vi.fn().mockResolvedValue(result),
    single: vi.fn().mockResolvedValue(result),
    then: (resolve: (v: unknown) => unknown) =>
      Promise.resolve(result).then(resolve),
    ...overrides,
  };
  return chain;
}

// ─── testes ─────────────────────────────────────────────────────────────────

describe('useSetores', () => {
  beforeEach(() => {
    vi.clearAllMocks();
  });

  // ── A. excluirSetor ────────────────────────────────────────────────────────

  describe('excluirSetor', () => {
    it('BLOQUEIA quando há itens ativos — retorna ok:false com contagem na mensagem e NÃO chama delete', async () => {
      // produtos_master: select com count retorna 3 ativos
      const produtosMasterChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        // A query termina sem .then explícito — a Promise é criada pelo then implícito.
        // Precisamos que a chain resolva { count: 3, error: null } quando awaited.
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ count: 3, error: null }).then(resolve),
      };

      // setores: não deve ser chamado (delete bloqueado)
      const setoresDeleteSpy = vi.fn();
      const setoresChain: Record<string, unknown> = {
        delete: setoresDeleteSpy,
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ data: [], error: null }).then(resolve),
      };

      setupFromMock({
        produtos_master: produtosMasterChain,
        setores: setoresChain,
      });

      const { result } = renderHook(() => useSetores(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.excluirSetor>>;
      await act(async () => {
        resultado = await result.current.excluirSetor('EMBALAGENS');
      });

      expect(resultado!.ok).toBe(false);
      expect(resultado!.error).toMatch(/3/); // mensagem contém o número
      expect(setoresDeleteSpy).not.toHaveBeenCalled();
    });

    it('deleta quando 0 itens ativos e retorna ok:true', async () => {
      const deleteSpy = vi.fn().mockReturnValue({
        eq: vi.fn().mockResolvedValue({ error: null }),
      });

      // produtos_master count = 0
      const produtosMasterChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ count: 0, error: null }).then(resolve),
      };

      // setores: delete encadeável que resolve sem erro
      const setoresChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        delete: deleteSpy,
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ data: [], error: null }).then(resolve),
      };

      setupFromMock({
        produtos_master: produtosMasterChain,
        setores: setoresChain,
      });

      const { result } = renderHook(() => useSetores(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.excluirSetor>>;
      await act(async () => {
        resultado = await result.current.excluirSetor('VAZIO');
      });

      expect(resultado!.ok).toBe(true);
      expect(deleteSpy).toHaveBeenCalled();
    });
  });

  // ── B. criarSetor ──────────────────────────────────────────────────────────

  describe('criarSetor', () => {
    it('normaliza para UPPERCASE antes de inserir', async () => {
      const insertSpy = vi.fn().mockResolvedValue({ error: null });

      // maybeSingle retorna null (setor não existe)
      const setoresChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        maybeSingle: vi.fn().mockResolvedValue({ data: null, error: null }),
        insert: insertSpy,
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ data: [], error: null }).then(resolve),
      };

      setupFromMock({ setores: setoresChain });

      const { result } = renderHook(() => useSetores(), {
        wrapper: createWrapper(),
      });

      await act(async () => {
        await result.current.criarSetor('embalagens especiais');
      });

      // O insert deve ter sido chamado com o nome em UPPERCASE
      expect(insertSpy).toHaveBeenCalledWith(
        expect.objectContaining({ nome: 'EMBALAGENS ESPECIAIS', ativo: true }),
      );
    });

    it('retorna ok:false quando setor ativo já existe (deduplicação)', async () => {
      const insertSpy = vi.fn();

      const setoresChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        // setor existente e ativo
        maybeSingle: vi.fn().mockResolvedValue({
          data: { nome: 'CÂMARA FRIA', ativo: true },
          error: null,
        }),
        insert: insertSpy,
        then: (resolve: (v: unknown) => unknown) =>
          Promise.resolve({ data: [], error: null }).then(resolve),
      };

      setupFromMock({ setores: setoresChain });

      const { result } = renderHook(() => useSetores(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.criarSetor>>;
      await act(async () => {
        resultado = await result.current.criarSetor('CÂMARA FRIA');
      });

      expect(resultado!.ok).toBe(false);
      expect(resultado!.error).toBe('Esse setor já existe.');
      expect(insertSpy).not.toHaveBeenCalled();
    });

    it('retorna ok:false para nome vazio', async () => {
      const { result } = renderHook(() => useSetores(), {
        wrapper: createWrapper(),
      });

      let resultado: Awaited<ReturnType<typeof result.current.criarSetor>>;
      await act(async () => {
        resultado = await result.current.criarSetor('   ');
      });

      expect(resultado!.ok).toBe(false);
      expect(resultado!.error).toBe('Informe um nome.');
    });
  });

  // ── C. atualizarProdutoSetorUnidade ────────────────────────────────────────

  describe('atualizarProdutoSetorUnidade', () => {
    it('chama update em produtos_master com setor e unidade_medida — nenhum outro campo', async () => {
      const updateSpy = vi.fn().mockReturnValue({
        eq: vi.fn().mockResolvedValue({ error: null }),
      });

      const produtosMasterChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
        update: updateSpy,
