      });

      // garantir que não foi chamado com campos como ativo, nome ou outros
      const chamadaArgs = updateSpy.mock.calls[0][0] as Record<string, unknown>;
      expect(Object.keys(chamadaArgs)).toHaveLength(2);
      expect(chamadaArgs).not.toHaveProperty('ativo');
    });

    it('retorna ok:true em caso de sucesso', async () => {
      const produtosMasterChain: Record<string, unknown> = {
        select: vi.fn().mockReturnThis(),
        eq: vi.fn().mockReturnThis(),
        order: vi.fn().mockReturnThis(),
